import { create } from "zustand";
import toast from "react-hot-toast";
import { Get, GetDetail, Post, Update, Delete } from "@/utils/apiMethods";
import { defaultPagination } from "@/constants";
import { sanitizeObject } from "@/utils/sanitize";

/**
 * Factory function to create a Zustand store with standard CRUD operations
 * @param {Object} config - Store configuration
 * @param {String} config.entityName - Entity name for toast messages (e.g., "Student", "Grade")
 * @param {String} config.baseUrl - Base URL for single entity operations (e.g., "student/")
 * @param {String} config.listUrl - URL for list operations (e.g., "students")
 * @param {Object} config.defaultForm - Default form state
 * @param {Object} config.defaultFilter - Default filter state
 * @param {Function} config.validateForm - Optional form validation function
 * @param {Function} config.preparePayload - Optional payload preparation function
 * @param {Function} config.transformFetchedData - Optional function to transform fetched data
 * @param {Object|Function} config.customMethods - Optional custom methods to add to the store
 * @param {Object} config.overrides - Optional method overrides {methodName: (set, get, baseMethod) => overriddenMethod}
 * @param {Object} config.apiMethods - Optional API method overrides {Get, GetDetail, Post, Update, Delete}
 * @returns {Function} Zustand store hook
 */
export function createCrudStore({
  entityName,
  baseUrl,
  listUrl,
  defaultForm = {},
  defaultFilter = { keyword: "", limit: 10, page: 1 },
  validateForm,
  preparePayload = (data) => data,
  transformFetchedData = (data) => data,
  customMethods = {},
  overrides = {},
  apiMethods = {},
}) {
  // Use provided API methods or fall back to defaults
  const {
    Get: GetMethod = Get,
    GetDetail: GetDetailMethod = GetDetail,
    Post: PostMethod = Post,
    Update: UpdateMethod = Update,
    Delete: DeleteMethod = Delete,
  } = apiMethods;
  return create((set, get) => {
    // Base methods
    const baseMethods = {
      // Filter management
      setFilter: (name, value) =>
        set(() => ({
          filter: {
            ...get().filter,
            [name]: value,
          },
        })),

      clearFilter: () =>
        set(() => ({
          filter: { ...defaultFilter },
        })),

      // Form management
      setForm: ({ name, value }) =>
        set(() => ({
          form: {
            ...get().form,
            [name]: value,
          },
        })),

      setEditData: (data) =>
        set(() => ({
          editData: data,
          form: data,
        })),

      clearFormData: () =>
        set(() => ({
          editData: {},
          formErrors: {},
          form: { ...defaultForm },
          isFormError: false,
          isFormLoading: false,
        })),

      // Data operations
      fetchData: async (params = {}) => {
        get().clearData();
        set({ isLoading: true });

        try {
          const response = await GetMethod(listUrl, params);
          if (response.isSuccess) {
            const { data, pagination } = response;
            set({
              data,
              pagination: pagination || { ...defaultPagination },
            });
          }
        } catch (error) {
          set({ errorMsg: error.message, isError: true });
        } finally {
          set({ isLoading: false });
        }
      },

      createRecord: async (data) => {
        if (validateForm) {
          const errors = validateForm(data);
          if (errors) {
            set({ formErrors: errors, isFormError: true });
            // Show toast with validation error
            const errorMessage =
              typeof errors === "object"
                ? Object.values(errors)[0]
                : "Validation failed";
            toast.error(errorMessage);
            return false;
          }
        }

        set({ isFormLoading: true });

        try {
          const sanitizedData = sanitizeObject(data);
          const payload = preparePayload(sanitizedData);
          const response = await PostMethod(baseUrl, payload, {}, entityName);

          if (response.isSuccess) {
            set({
              data: [...get().data, response.data],
              isFormError: false,
              isFormLoading: false,
            });
            return true;
          }

          set({
            formErrors: response.errors,
            isFormError: true,
            isFormLoading: false,
          });
          return false;
        } catch (error) {
          set({ formErrors: error, isFormError: true, isFormLoading: false });
          return false;
        }
      },

      fetchRecord: async (id) => {
        get().clearData();
        set({ isLoading: true });

        try {
          const response = await GetDetailMethod(baseUrl, id);
          if (response.isSuccess) {
            const data = transformFetchedData(response.data);

            set({
              editData: { ...data },
              form: { ...data },
            });
          } else {
            set({ isError: true, errorMsg: response.message });
          }
        } catch (error) {
          set({ isError: true, errorMsg: error.message });
          return false;
        } finally {
          set({ isLoading: false });
        }
      },

      updateRecord: async (id, data) => {
        if (validateForm) {
          const errors = validateForm(data);
          if (errors) {
            set({ formErrors: errors, isFormError: true });
            // Show toast with validation error
            const errorMessage =
              typeof errors === "object"
                ? Object.values(errors)[0]
                : "Validation failed";
            toast.error(errorMessage);
            return false;
          }
        }

        set({ isFormLoading: true });

        try {
          const sanitizedData = sanitizeObject(data);
          const payload = preparePayload(sanitizedData);
          const response = await UpdateMethod(baseUrl, id, payload, {}, entityName);

          if (response.isSuccess) {
            set({ isFormError: false, isFormLoading: false });
            return true;
          }

          set({
            formErrors: response.errors,
            isFormError: true,
            isFormLoading: false,
          });
          return false;
        } catch (error) {
          set({ formErrors: error, isFormError: true, isFormLoading: false });
          return false;
        }
      },

      deleteRecord: async (id) => {
        set({ isDeleting: true });

        try {
          const response = await DeleteMethod(baseUrl, id, entityName);

          if (response.isSuccess) {
            set({ isDeleting: false });
            return true;
          }

          return false;
        } catch {
          set({ isDeleting: false });
          return false;
        }
      },

      fetchDataOptions: async (params = {}) => {
        set({ isFilterLoading: true, dataFilters: [], isFilterError: true });

        try {
          const response = await Get(listUrl + "/filter-options", params);
          if (response.isSuccess) {
            const { data } = response;
            set({ dataFilters: data, isFilterError: false });
          }
        } catch (error) {
          set({ filterErrorMsg: error.message, isFilterError: true });
        } finally {
          set({ isFilterLoading: false });
        }
      },

      clearData: () =>
        set(() => ({
          data: [],
          pagination: { ...defaultPagination },
          errorMsg: "",
          isError: false,
          isLoading: true,
        })),
    };

    // Apply overrides to base methods
    const finalMethods = {};
    Object.keys(baseMethods).forEach((key) => {
      if (overrides[key]) {
        // Allows overriding with access to set, get, and base implementation
        finalMethods[key] = overrides[key](set, get, baseMethods[key]);
      } else {
        finalMethods[key] = baseMethods[key];
      }
    });

    // Return store state and methods
    return {
      // State
      data: [],
      dataFilters: [],
      pagination: { ...defaultPagination },
      filter: { ...defaultFilter },
      form: { ...defaultForm },
      editData: {},
      formErrors: {},
      errorMsg: "",
      filterErrorMsg: "",
      isLoading: true,
      isError: false,
      isFilterLoading: false,
      isFilterError: false,
      isFormLoading: false,
      isFormError: false,
      isDeleting: false,

      // Methods (base + overridden)
      ...finalMethods,

      // Custom methods
      ...(typeof customMethods === "function"
        ? customMethods(set, get)
        : customMethods),
    };
  });
}
