import axios from "axios";
import { useMemo, useState } from "react";
import { DownloadIcon } from "./icons/index.jsx";

// Inlined utility functions
function saveBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

function parseFilenameFromContentDisposition(contentDisposition) {
  if (!contentDisposition) return null;
  const match = contentDisposition.match(/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/);
  if (match && match[1]) {
    return match[1].replace(/['"]/g, '');
  }
  return null;
}

export default function FileDownloader({ url, className = "", file }) {
  const [progress, setProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(false);

  async function handleDownload() {
    setIsLoading(true);
    setProgress(0);

    try {
      const resp = await axios.get(url, {
        responseType: "blob",
        onDownloadProgress: (evt) => {
          if (evt.lengthComputable || evt.total) {
            const total = evt.total || 0;
            const pct = total ? Math.round((evt.loaded * 100) / total) : 0;
            setProgress(pct);
          } else {
            setProgress((prev) => Math.min(prev + 5, 99));
          }
        },
      });

      const cd =
        resp.headers["content-disposition"] ||
        resp.headers["Content-Disposition"];
      const filename =
        parseFilenameFromContentDisposition(cd) ||
        new URL(url).pathname.split("/").pop() ||
        "download";

      saveBlob(resp.data, filename);

      setProgress(100);
    } catch (err) {
      console.error("Download error", err);

      const message = err?.response?.data
        ? "Server responded with an error"
        : err.message || "Unknown error";
      alert(`Download failed: ${message}`);
    } finally {
      setTimeout(
        () => {
          setIsLoading(false);
          setTimeout(() => setProgress(0), 300);
        },
        progress >= 100 ? 600 : 200,
      );
    }
  }

  const displayedName = useMemo(() => {
    if (!file) return "File name";

    if (file instanceof File) {
      return file.name || "";
    }

    if (Object.keys(file)?.length > 0) {
      return file.originalname;
    }

    return "File name";
  }, [file]);

  return (
    <div className={`w-full max-w-sm ${className}`}>
      <button
        type="button"
        className={`w-full border-2 border-dotted border-[#2563EB] input-field-wrapper justify-between ${isLoading ? "bg-slate-300 text-slate-700 cursor-not-allowed" : "bg-blue-600 hover:bg-blue-700 text-white"} duration-300 transition`}
        onClick={handleDownload}
        disabled={isLoading}
        aria-live="polite"
        aria-busy={isLoading}
        aria-disabled={isLoading}
      >
        <span className="w-full cursor-pointer text-[#898989] flex justify-start items-center gap-3 bg-current truncate">
          {isLoading ? <span>Downloading… {progress}%</span> : displayedName}
        </span>
        <span type="button">
          <DownloadIcon />
        </span>
      </button>

      {/* Progress bar */}
      <div
        className="mt-3 h-3 bg-slate-100 rounded-md overflow-hidden"
        aria-hidden={!isLoading}
      >
        <div
          className="h-full rounded-md shadow-inner transform transition-all duration-200 ease-out"
          style={{ width: `${isLoading ? progress : 0}%` }}
        />
      </div>
    </div>
  );
}
