import PropTypes from "prop-types";
import {
  Modal,
  ModalContent,
  ModalFooter,
  ModalHeader,
  ModalBody,
} from "@nextui-org/react";
import Button from "./button";

const ModalBox = ({
  header = "Header",
  title = "Title",
  cancelText = "No",
  confirmText = "Yes",
  size = "lg",
  isOpen = false,
  isBtnDisabled = false,
  classNames = {},
  children,
  onClose,
  onKeyDown,
}) => {
  return (
    <Modal
      backdrop="blur"
      size={size}
      isOpen={isOpen}
      onClose={onClose}
      closeButton
      classNames={classNames}
    >
      <ModalContent>
        {() => (
          <>
            <ModalHeader className="flex flex-col gap-1">{header}</ModalHeader>
            <ModalBody>
              <p>{title}</p>
              {children}
            </ModalBody>
            <ModalFooter>
              <Button
                color="default"
                variant="light"
                onPress={onClose}
                isDisabled={isBtnDisabled}
              >
                {cancelText}
              </Button>
              <Button
                color="danger"
                onKeyDown={onKeyDown}
                onPress={onKeyDown}
                isDisabled={isBtnDisabled}
              >
                {confirmText}
              </Button>
            </ModalFooter>
          </>
        )}
      </ModalContent>
    </Modal>
  );
};

ModalBox.propTypes = {
  header: PropTypes.string,
  title: PropTypes.string,
  cancelText: PropTypes.string,
  confirmText: PropTypes.string,
  size: PropTypes.string,
  isOpen: PropTypes.bool,
  isBtnDisabled: PropTypes.bool,
  classNames: PropTypes.any,
  children: PropTypes.any,
  onClose: PropTypes.func,
  onKeyDown: PropTypes.func,
};

export default ModalBox;
