/**
 * API Configuration Module
 * Provides configuration options for creating customizable API clients
 */

/**
 * @typedef {Object} ApiConfig
 * @property {string} [baseURL] - Base URL for API requests (default: import.meta.env.VITE_API_BASE_URL)
 * @property {string} [tokenKey] - localStorage key for authentication token (default: '@token')
 * @property {string} [userKey] - localStorage key for user data (default: '@authenticatedUser')
 * @property {Object} [headers] - Default headers for requests (default: { 'Content-Type': 'application/json' })
 * @property {Function} [requestInterceptor] - Custom request interceptor function
 * @property {Function} [responseInterceptor] - Custom response interceptor function
 * @property {Function} [errorInterceptor] - Custom error interceptor function
 * @property {Function} [onSuccess] - Success notification handler (receives message string)
 * @property {Function} [onError] - Error notification handler (receives message string)
 * @property {boolean} [includeBranchLogic] - Include relatedBranch logic in interceptor (default: true)
 * @property {boolean} [includeCreatedBy] - Include createdBy field in requests (default: true)
 * @property {Function} [transformRequest] - Custom request transformer
 * @property {Function} [transformResponse] - Custom response transformer
 */

/**
 * Default configuration values
 * @type {ApiConfig}
 */
export const defaultConfig = {
  baseURL: typeof import.meta !== 'undefined' && import.meta.env?.VITE_API_BASE_URL 
    ? import.meta.env.VITE_API_BASE_URL 
    : 'http://localhost:3000',
  tokenKey: '@token',
  userKey: '@authenticatedUser',
  headers: {
    'Content-Type': 'application/json',
  },
  includeBranchLogic: true,
  includeCreatedBy: true,
  onSuccess: null, // Will use default notification handler if not provided
  onError: null, // Will use default notification handler if not provided
};

/**
 * Merges user configuration with default configuration
 * @param {ApiConfig} userConfig - User-provided configuration
 * @returns {ApiConfig} Merged configuration
 */
export const mergeConfig = (userConfig = {}) => {
  return {
    ...defaultConfig,
    ...userConfig,
    headers: {
      ...defaultConfig.headers,
      ...(userConfig.headers || {}),
    },
  };
};

/**
 * Default success notification handler
 * Uses react-hot-toast if available, falls back to console
 * @param {string} message - Success message
 */
export const defaultSuccessHandler = (message) => {
  try {
    // Try to use react-hot-toast if available
    if (typeof window !== 'undefined' && window.toast) {
      window.toast.success(message);
    } else {
      // Try dynamic import
      import('react-hot-toast')
        .then(({ default: toast }) => toast.success(message))
        .catch(() => console.log('✓', message));
    }
  } catch (error) {
    console.log('✓', message);
  }
};

/**
 * Default error notification handler
 * Uses react-hot-toast if available, falls back to console
 * @param {string} message - Error message
 */
export const defaultErrorHandler = (message) => {
  try {
    // Try to use react-hot-toast if available
    if (typeof window !== 'undefined' && window.toast) {
      window.toast.error(message);
    } else {
      // Try dynamic import
      import('react-hot-toast')
        .then(({ default: toast }) => toast.error(message))
        .catch(() => console.error('✗', message));
    }
  } catch (error) {
    console.error('✗', message);
  }
};

/**
 * Get the appropriate success handler
 * @param {ApiConfig} config - Configuration object
 * @returns {Function} Success handler function
 */
export const getSuccessHandler = (config) => {
  return config.onSuccess || defaultSuccessHandler;
};

/**
 * Get the appropriate error handler
 * @param {ApiConfig} config - Configuration object
 * @returns {Function} Error handler function
 */
export const getErrorHandler = (config) => {
  return config.onError || defaultErrorHandler;
};

/**
 * Validates the configuration object
 * @param {ApiConfig} config - Configuration to validate
 * @throws {Error} If configuration is invalid
 */
export const validateConfig = (config) => {
  if (config.baseURL && typeof config.baseURL !== 'string') {
    throw new Error('baseURL must be a string');
  }
  
  if (config.tokenKey && typeof config.tokenKey !== 'string') {
    throw new Error('tokenKey must be a string');
  }
  
  if (config.userKey && typeof config.userKey !== 'string') {
    throw new Error('userKey must be a string');
  }
  
  if (config.onSuccess && typeof config.onSuccess !== 'function') {
    throw new Error('onSuccess must be a function');
  }
  
  if (config.onError && typeof config.onError !== 'function') {
    throw new Error('onError must be a function');
  }
};
