import { useMemo } from "react";
import PropTypes from "prop-types";
import { Link, useLocation } from "react-router-dom";

const linkBaseClasses =
  "my-1 w-full p-3 flex items-center gap-2 border border-gray-200 text-base rounded-lg transition-all duration-300";

const NavLinkItem = ({ path, title, icon }) => {
  const location = useLocation();

  const activeClasses = useMemo(() => {
    // Remove query params and trailing slash for comparison
    const currentPath = location.pathname.split("?")[0].replace(/\/$/, "");
    const linkPath = path.replace(/\/$/, "");

    // Check for exact match or if current path starts with link path (for child routes)
    // This ensures /vouchers-list matches when on /vouchers-details/123
    // but /master-data/categories won't match when on /master-data/sub-categories
    const isActive =
      currentPath === linkPath || currentPath.startsWith(linkPath + "/");

    if (isActive)
      return "bg-red-50 text-red-900 font-semibold border-red-900";
    return "bg-white text-gray-700 hover:bg-red-50 hover:text-red-800 hover:border-red-200";
  }, [location.pathname, path]);

  return (
    <Link to={path} className={`${linkBaseClasses} ${activeClasses}`}>
      {icon && <span className="flex-shrink-0">{icon}</span>}
      {title && <span className="truncate">{title}</span>}
    </Link>
  );
};

NavLinkItem.propTypes = {
  path: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  icon: PropTypes.node,
};

export default NavLinkItem;
