import axios from "axios";
import { mergeConfig, validateConfig } from "./apiConfig";

/**
 * Creates a default request interceptor with branch and user logic
 * @param {Object} config - API configuration
 * @returns {Function} Request interceptor function
 */
export const createDefaultRequestInterceptor = (config) => {
  return (axiosConfig) => {
    const token = localStorage.getItem(config.tokenKey);
    const localUser = localStorage.getItem(config.userKey);

    let user = {};
    try {
      user = localUser ? JSON.parse(localUser) : {};
    } catch (error) {
      console.error("Error parsing user data:", error);
    }

    if (token) {
      axiosConfig.headers.Authorization = `Bearer ${token}`;

      // Only include branch logic if enabled in config
      if (config.includeBranchLogic) {
        const relatedBranch = user.relatedBranch?._id || user.relatedBranch;

        if (relatedBranch) {
          axiosConfig.params = {
            ...axiosConfig.params,
            relatedBranch: relatedBranch,
          };

          if (["post", "put", "patch"].includes(axiosConfig.method)) {
            if (axiosConfig.data instanceof FormData) {
              if (!axiosConfig.data.has("relatedBranch"))
                axiosConfig.data.append("relatedBranch", relatedBranch);
              else if (!axiosConfig.data.get("relatedBranch"))
                axiosConfig.data.set("relatedBranch", relatedBranch);

              if (config.includeCreatedBy) {
                if (
                  !axiosConfig.data.has("createdBy") ||
                  !axiosConfig.data.get("createdBy")
                )
                  axiosConfig.data.append("createdBy", user._id || user.id);
                else if (!axiosConfig.data.get("createdBy"))
                  axiosConfig.data.set("createdBy", user._id || user.id);
              }
            } else {
              const additionalData = {
                relatedBranch,
              };
              
              if (config.includeCreatedBy) {
                additionalData.createdBy = user._id || user.id;
              }
              
              axiosConfig.data = {
                ...axiosConfig.data,
                ...additionalData,
              };
            }
          }
        }
      }
    }

    // Apply custom transform if provided
    if (config.transformRequest) {
      return config.transformRequest(axiosConfig, user, token);
    }

    return axiosConfig;
  };
};

/**
 * Creates a simple request interceptor (token only, no branch logic)
 * @param {Object} config - API configuration
 * @returns {Function} Request interceptor function
 */
export const createSimpleRequestInterceptor = (config) => {
  return (axiosConfig) => {
    const token = localStorage.getItem(config.tokenKey);

    if (token) {
      axiosConfig.headers.Authorization = `Bearer ${token}`;
    }

    return axiosConfig;
  };
};

/**
 * Applies interceptors to an axios instance
 * @param {Object} axiosInstance - Axios instance
 * @param {Object} config - API configuration
 * @returns {Object} Axios instance with interceptors
 */
export const applyInterceptors = (axiosInstance, config) => {
  // Request interceptor
  axiosInstance.interceptors.request.use(
    config.requestInterceptor || createDefaultRequestInterceptor(config),
    (error) => {
      return Promise.reject(error);
    }
  );

  // Response interceptor
  if (config.responseInterceptor) {
    axiosInstance.interceptors.response.use(
      config.responseInterceptor,
      config.errorInterceptor || ((error) => Promise.reject(error))
    );
  } else if (config.errorInterceptor) {
    axiosInstance.interceptors.response.use(
      (response) => response,
      config.errorInterceptor
    );
  }

  return axiosInstance;
};

/**
 * Creates a configured axios instance
 * @param {Object} userConfig - User-provided configuration
 * @returns {Object} Configured axios instance
 */
export const createApiClient = (userConfig = {}) => {
  // Validate and merge configuration
  validateConfig(userConfig);
  const config = mergeConfig(userConfig);

  // Create axios instance
  const axiosInstance = axios.create({
    baseURL: config.baseURL,
    headers: config.headers,
  });

  // Apply interceptors
  return applyInterceptors(axiosInstance, config);
};

/**
 * Backward compatibility: customAxios function
 * @param {string} dynamicBaseURL - Base URL for the API
 * @returns {Object} Configured axios instance
 */
export const customAxios = (dynamicBaseURL) => {
  if (dynamicBaseURL) {
    return createApiClient({ baseURL: dynamicBaseURL });
  }
  return createApiClient();
};

// Default instances for backward compatibility
const defaultBaseURL = typeof import.meta !== 'undefined' && import.meta.env?.VITE_API_BASE_URL 
  ? import.meta.env.VITE_API_BASE_URL 
  : 'http://localhost:3000';

export const api = axios.create({
  baseURL: defaultBaseURL,
  headers: {
    "Content-Type": "application/json",
  },
});

// Backward compatibility: apiInterception function
export const apiInterception = (apiInstance) => {
  const config = mergeConfig();
  return applyInterceptors(apiInstance, config);
};

// Default instance with interceptors
export const apiInstance = createApiClient();

// Image URL helper
export const ImageURL = defaultBaseURL + "uploads/";
