import PropTypes from "prop-types";
import {
  Table,
  TableHeader,
  TableColumn,
  TableBody,
  TableRow,
  TableCell,
  Pagination,
  Spinner,
} from "@nextui-org/react";
import { perPageOptions } from "@/constants";

/**
 * Reusable DataTable component for list pages
 * @param {Array} columns - Array of column definitions {key, label, render?}
 * @param {Array} data - Array of data items to display
 * @param {Object} pagination - Pagination info {total, totalPages}
 * @param {Object} filter - Current filter state {page, limit}
 * @param {Boolean} isLoading - Loading state
 * @param {Boolean} isError - Error state
 * @param {String} errorMsg - Error message to display
 * @param {Function} onFilterChange - Filter change handler
 * @param {String} emptyMessage - Message when no data
 * @param {String} ariaLabel - Accessible label for table
 */
export default function DataTable({
  columns = [],
  data = [],
  pagination = { total: 0, totalPages: 1 },
  filter = { page: 1, limit: 10 },
  isLoading = false,
  isError = false,
  errorMsg = "",
  onFilterChange,
  emptyMessage = "No data to display",
  ariaLabel = "Data Table",
}) {
  const handleLimitChange = (e) => {
    onFilterChange({
      name: e.target.name,
      value: parseFloat(e.target.value),
    });
  };

  const handlePageChange = (page) => {
    onFilterChange({
      name: "page",
      value: parseFloat(page),
    });
  };

  return (
    <>
      <div className="flex justify-between items-center">
        <span className="text-default-400 text-small">
          Total {pagination?.total || 0} items
        </span>
        <label
          htmlFor="limit"
          className="flex items-center text-default-400 text-small"
        >
          Rows per page:
          <select
            id="limit"
            name="limit"
            className="bg-transparent outline-none text-default-400 text-small"
            value={filter.limit}
            onChange={handleLimitChange}
          >
            {perPageOptions.map((pageSize) => (
              <option key={pageSize} value={pageSize}>
                {pageSize}
              </option>
            ))}
          </select>
        </label>
      </div>

      <Table
        isHeaderSticky
        aria-label={ariaLabel}
        bottomContent={
          <div className="flex w-full justify-center">
            <Pagination
              isCompact
              showControls
              showShadow
              color="primary"
              page={filter.page}
              total={pagination?.totalPages || 1}
              onChange={handlePageChange}
            />
          </div>
        }
      >
        <TableHeader>
          {columns.map((col) => (
            <TableColumn key={col.key}>{col.label}</TableColumn>
          ))}
        </TableHeader>

        {isLoading ? (
          <TableBody emptyContent={<Spinner />}></TableBody>
        ) : (
          <TableBody emptyContent={isError ? errorMsg : emptyMessage}>
            {data?.map((item, index) => (
              <TableRow key={item._id || index}>
                {columns.map((col) => (
                  <TableCell key={col.key}>
                    {col.render ? col.render(item, index) : item[col.key]}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        )}
      </Table>
    </>
  );
}

DataTable.propTypes = {
  columns: PropTypes.arrayOf(
    PropTypes.shape({
      key: PropTypes.string.isRequired,
      label: PropTypes.string.isRequired,
      render: PropTypes.func,
    }),
  ).isRequired,
  data: PropTypes.array,
  pagination: PropTypes.shape({
    total: PropTypes.number,
    totalPages: PropTypes.number,
  }),
  filter: PropTypes.shape({
    page: PropTypes.number,
    limit: PropTypes.number,
  }),
  isLoading: PropTypes.bool,
  isError: PropTypes.bool,
  errorMsg: PropTypes.string,
  onFilterChange: PropTypes.func.isRequired,
  emptyMessage: PropTypes.string,
  ariaLabel: PropTypes.string,
};
