import { customAxios } from "./axiosInstance";
import { getSuccessHandler, getErrorHandler, mergeConfig } from "./apiConfig";
import { errorResponse, successResponse } from "@/helpers/response";

/**
 * @typedef {Object} CrudOptions
 * @property {Function} [onSuccess] - Custom success handler
 * @property {Function} [onError] - Custom error handler
 * @property {boolean} [showNotification] - Whether to show notifications (default: true)
 * @property {string} [customSuccessMessage] - Custom success message
 * @property {string} [customErrorMessage] - Custom error message
 * @property {Object} [apiConfig] - API configuration for this request
 */

/**
 * Handles success notification
 * @param {string} message - Success message
 * @param {CrudOptions} options - CRUD options
 */
const handleSuccess = (message, options = {}) => {
  if (options.showNotification === false) return;
  
  const config = mergeConfig(options.apiConfig);
  const successHandler = options.onSuccess || getSuccessHandler(config);
  
  const finalMessage = options.customSuccessMessage || message;
  successHandler(finalMessage);
};

/**
 * Handles error notification
 * @param {string} message - Error message
 * @param {CrudOptions} options - CRUD options
 */
const handleError = (message, options = {}) => {
  if (options.showNotification === false) return;
  
  const config = mergeConfig(options.apiConfig);
  const errorHandler = options.onError || getErrorHandler(config);
  
  const finalMessage = options.customErrorMessage || message;
  errorHandler(finalMessage);
};

/**
 * GET request
 * @param {string} url - Request URL
 * @param {Object} params - Query parameters
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<Object>} Response data
 */
export const Get = async (url, params = {}, api = customAxios(), options = {}) => {
  try {
    const response = await api.get(url, { params });
    return response.data;
  } catch (error) {
    if (error.status == "404")
      return {
        isSuccess: true,
        data: [],
      };

    const errorMessage = error?.response?.data?.message || "Request failed";
    handleError(errorMessage, options);

    return {
      success: false,
      data: [],
      message: errorMessage,
    };
  }
};

/**
 * POST request with email notification (using SweetAlert2)
 * @param {string} url - Request URL
 * @param {Object} data - Request payload
 * @param {Object} conf - Axios config
 * @param {string} text - Text for notification (e.g., "email")
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<any>} Response data
 */
export const EmailWithPost = async (
  url,
  data,
  conf,
  text,
  api = customAxios(),
  options = {},
) => {
  try {
    // Try to use Swal if available
    const Swal = await import('sweetalert2').catch(() => null);
    
    const res = await api.post(url, data, conf);
    
    if (Swal?.default) {
      Swal.default.fire({
        title: "Successful!",
        text: `Check your ${text} for password!`,
        icon: "success",
        showConfirmButton: false,
        timer: 4000,
      });
    } else {
      handleSuccess(`Check your ${text} for password!`, options);
    }

    return res.data.data;
  } catch (err) {
    const Swal = await import('sweetalert2').catch(() => null);
    const errorMessage = err.response?.data?.message || "Request failed";
    
    if (Swal?.default) {
      Swal.default.fire({
        title: "Something Wrong!",
        text: errorMessage,
        icon: "warning",
        showConfirmButton: false,
        timer: 2000,
      });
    } else {
      handleError(errorMessage, options);
    }
  }
};

/**
 * POST request
 * @param {string} url - Request URL
 * @param {Object} data - Request payload
 * @param {Object} config - Axios config
 * @param {string} text - Entity name for notification (e.g., "user")
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<Object>} Response data
 */
export const Post = async (
  url,
  data,
  config = {},
  text,
  api = customAxios(),
  options = {},
) => {
  try {
    const res = await api.post(url, data, config);
    if (res.data.isSuccess) {
      if (url.split("?")[0] === "auth/login") {
        handleSuccess("Login successfully!", options);
      } else {
        handleSuccess(`The ${text} had been created successfully!`, options);
      }
    }
    return res.data;
  } catch (error) {
    const errorMessage = error.response?.data?.message || "Request failed";
    handleError(errorMessage, options);

    return errorResponse(errorMessage, []);
  }
};

/**
 * POST request with FormData
 * @param {string} url - Request URL
 * @param {FormData} data - FormData payload
 * @param {Object} config - Axios config
 * @param {string} text - Entity name for notification
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<Object>} Response data
 */
export const PostWithFormData = async (
  url,
  data,
  config = {},
  text,
  api = customAxios(),
  options = {},
) => {
  return await Post(
    url,
    data,
    {
      headers: {
        "Content-Type": "multipart/form-data",
      },
      ...config,
    },
    text,
    api,
    options,
  );
};

/**
 * PUT/UPDATE request
 * @param {string} url - Request URL (without ID)
 * @param {string} id - Entity ID
 * @param {Object} data - Request payload
 * @param {Object} conf - Axios config
 * @param {string} text - Entity name for notification
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<Object>} Response data
 */
export const Update = async (
  url,
  id,
  data,
  conf,
  text,
  api = customAxios(),
  options = {},
) => {
  try {
    const res = await api.put(url + id, data, conf);
    if (res.data.isSuccess) {
      handleSuccess("Saved Your Changes!", options);
    } else {
      handleError("Something Wrong!", options);
    }

    return res.data;
  } catch (error) {
    const errorMessage = error.response?.data?.message || "Update failed";
    handleError(errorMessage, options);

    return errorResponse(errorMessage, []);
  }
};

