/**
 * GET detail request (GET by ID)
 * @param {string} url - Request URL (without ID)
 * @param {string} id - Entity ID
 * @param {Object} params - Query parameters
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<Object>} Response data
 */
export const GetDetail = async (url, id, params = {}, api = customAxios(), options = {}) => {
  return await Get(url + id, params, api, options);
};

/**
 * DELETE request
 * @param {string} url - Request URL (without ID)
 * @param {string} id - Entity ID
 * @param {string} text - Entity name for notification
 * @param {Object} api - Axios instance
 * @param {CrudOptions} options - Additional options
 * @returns {Promise<boolean>} Success status
 */
export const Delete = async (url, id, text, api = customAxios(), options = {}) => {
  try {
    const res = await api.delete(url + id);

    if (res.data.isSuccess) {
      handleSuccess(`The ${text} had been deleted successfully!`, options);
    }

    return true;
  } catch (error) {
    const errorMessage = error.response?.data?.message || "Delete failed";
    handleError(errorMessage, options);

    return false;
  }
};

/**
 * Validates form fields
 * @param {Array<Object>} fieldChecks - Array of field validation objects
 * @param {CrudOptions} options - Additional options
 * @returns {Object} Validation result
 */
export const ValidateForm = (fieldChecks, options = {}) => {
  const requiredFields = [];
  const customErrorMsgs = [];

  fieldChecks.forEach(
    ({
      condition,
      label,
      customMsg = "",
      isRequired = false,
      isCustom = false,
    }) => {
      if (condition) {
        if (isRequired) requiredFields.push(label);
        if (isCustom) customErrorMsgs.push(customMsg);
      }
    },
  );

  if (requiredFields.length > 0) {
    const message = `These field(s) are required to fill: ${requiredFields.join(", ")}`;
    handleError(message, options);
    return errorResponse(message);
  }

  if (customErrorMsgs.length > 0) {
    const message = `Validation Error: ${customErrorMsgs.join(",\n")}`;
    handleError(message, options);
    return errorResponse(message);
  }

  return successResponse();
};
